// The almanac's everyday talk of 1899 (Core/Almanac.cs): what Americans were talking about all that year, with no date
// to it. The prices and the catalogue, the wheel and the horseless carriage, the phonograph, the songs and the books,
// the medicines, the trusts, the old names of the West and where they'd got to. Month 0: known all year. The telephone
// came in on 2026-11-04 (Lex: "let all of these real 1899 thoughts in"): the big towns have it, the small ones hear of it.
namespace EnrageWestworld.Core
{
    public static partial class Almanac
    {
        private static readonly AlmanacEvent[] Everyday1899 =
        {
            // ---- money and work --------------------------------------------------------------------------------
            E("goodtimes", 1899, 0, 0, null, 2, "money", "THE GOOD TIMES ARE BACK, THE PAPERS SAY",
              "After six lean years the mills are running, wheat and cattle bring a price, and the administration calls it prosperity in every speech.",
              "Paper says the hard times are over. Prosperity. I'll believe it when the store wipes my name off the slate.",
              "Everything sells this year. Wheat, beef, wool. Six lean years, and now the buyers come to you."),
            E("cattleprices", 1899, 0, 0, "west", 2, "money", "STEERS BRING THE BEST PRICE IN YEARS",
              "Fat steers are bringing more at the Chicago yards than at any time since the panic, and the ranges are shipping everything that can walk.",
              "Steers are up at Chicago, best price since '92. Every outfit's shipping anything with four legs and a hide.",
              "Beef's dear this year. The ranch is paying off the bank for once, instead of the other way about."),
            E("wheatcorn", 1899, 0, 0, "west", 1, "money", "A FAIR YEAR FOR THE GRAIN",
              "The wheat and corn are in and the price holds, and the elevators along the railroad are full for the first time in years.",
              "Wheat's holding its price this year. The elevator man smiles now. He never did before.",
              "Corn in and sold at a fair price. A dry year would have ruined us. This one just tired us out."),
            E("cowhandwages", 1899, 0, 0, "west", 1, "money", "THE WAGES OF THE RANGE",
              "A cowhand draws thirty dollars a month and found, a top hand forty, and a sheepherder about the same for a lonelier life.",
              "Thirty a month and beans. That's a cowhand's whole fortune. The horse is worth more than the man.",
              "Forty dollars for a top hand. Same as my father got in '79. Everything's gone up but us."),
            E("thetrusts", 1899, 0, 0, null, 2, "money", "THE YEAR OF THE TRUSTS",
              "More companies have been combined into trusts this year than in all the years before: steel, sugar, tin, whiskey, paper, matches, and the smelters.",
              "Everything's a trust now. Sugar, matches, whiskey. One company and one price for each. Who voted for that?",
              "They made a trust of tin plate this week and biscuits the week before. Soon there'll be a trust of trusts."),
            E("tariff", 1899, 0, 0, null, 1, "politics", "THE TARIFF AND THE PRICE OF EVERYTHING",
              "The Dingley tariff keeps foreign goods dear so the mills can prosper, and the farmer pays it on every nail and yard of cloth he buys.",
              "The tariff's why a yard of cloth costs what it does. Protects the mills back East. From me, mostly.",
              "Republicans say the tariff made the good times. I say it made the price of a plow."),
            E("goldsilver", 1899, 0, 0, null, 1, "politics", "GOLD OR SILVER, STILL",
              "The gold men mean to make gold the law next year, and the silver men still cry sixteen to one; the mines of the mountains cry with them.",
              "Still gold against silver in the papers. Three years since Bryan and they're still fighting it.",
              "Sixteen to one. Say it in a Colorado saloon and you've friends. Say it in Boston and you've none."),
            E("carnegielibrary", 1899, 0, 0, null, 1, "life", "MR. CARNEGIE OFFERS LIBRARIES TO ANY TOWN",
              "Andrew Carnegie will build a library for any town that promises to keep it stocked, and towns across the country are writing to Pittsburgh.",
              "Carnegie will give any town a library if the town buys the books. The council can't agree on a fence.",
              "A free library from the steel man. Buy his rails and he'll give you back a building to read in."),
            E("railroadkings", 1899, 0, 0, null, 1, "money", "HARRIMAN AND HILL BUY THE RAILROADS",
              "Mr. Harriman has the Union Pacific and Mr. Hill the Great Northern, and the papers say the two of them mean to own every rail west of Chicago.",
              "Two men own the railroads now, Harriman and Hill. They'll divide the West between them like a pie.",
              "The Union Pacific's one man's property, Harriman's. The road that crossed the country is a rich man's toy."),
            E("sheepcattle", 1899, 0, 0, "west", 1, "west", "SHEEP AND CATTLE ON THE SAME GRASS",
              "The sheepmen push into cattle range all along the mountains, and the cattlemen answer with the dead-line and sometimes the rifle.",
              "Sheep on the cattle range again. The cowmen drew a line and the sheepmen crossed it. Somebody's shot by fall.",
              "Sheep eat the grass to the root and cattle starve after them. That's not politics; that's a sheep's mouth."),
            E("wolfbounty", 1899, 0, 0, "west", 1, "west", "THE WOLF BOUNTY RAISED",
              "The stock associations have raised the bounty on wolves again, and a good wolfer with poison and traps can make more than a hand.",
              "Wolf bounty's five dollars now. A wolfer with strychnine makes more than me. And sleeps alone, which is fair.",
              "The wolves took forty calves on the north range. The stock association's paying bounty on ears now."),
            E("cripplecreek", 1899, 0, 0, "high", 2, "money", "CRIPPLE CREEK THE RICHEST CAMP IN THE WORLD",
              "The Cripple Creek district will turn out more gold this year than any camp on earth, the papers say, and its stock is sold on every corner of Denver.",
              "Cripple Creek's the richest gold camp in the world this year, the paper says. Every Denver clerk owns a share.",
              "More gold out of Cripple Creek than the Klondike, and it's a train ride from Denver. Nobody freezes for it."),
            E("silverlow", 1899, 0, 0, "high", 1, "money", "SILVER STAYS DOWN",
              "Silver is worth half what it was when the mines were opened, and the camps that lived on it live on gold now or not at all.",
              "Silver's not worth digging. The silver camps are ghost towns or gold now. Leadville hangs on by lead.",
              "Half the silver mines in the mountains are shut. You can walk through a town of five thousand and meet nobody."),
            E("leisureclass", 1899, 0, 0, null, 1, "money", "A PROFESSOR ON THE SPENDING OF THE RICH",
              "A Chicago professor named Veblen has a book out saying the rich buy fine things chiefly to be seen buying them.",
              "A Chicago professor says the rich buy fine things just to be seen buying them. Took him a book to say it.",
              "Veblen, the professor. Says a rich man's wife wears silk to show he needn't work. My wife wears calico."),
            // ---- the new things --------------------------------------------------------------------------------
            E("horseless", 1899, 0, 0, null, 2, "wonder", "THE HORSELESS CARRIAGE COMES WEST",
              "Horseless carriages are built in a dozen cities now, by steam, gasoline and electricity, and one has been seen as far west as Denver.",
              "There's a horseless carriage in Denver. Steam. Makes a noise like a train and goes slower than a trot.",
              "Horseless carriages. Four in the whole state and every one broke down. A horse don't break down; it dies."),
            E("trolley", 1899, 0, 0, null, 1, "wonder", "THE TROLLEY IN EVERY CITY",
              "Electric streetcars run in every city of size now, the horsecars gone to the scrap yard, and a nickel carries a man from one end of town to the other.",
              "The cities all have electric trolleys now. A nickel takes you across town. The horsecar's gone for good.",
              "Rode the trolley in Denver. Sparks off the wire and no horse at all. I held my hat the whole way."),
            E("electriclight", 1899, 0, 0, null, 1, "wonder", "ELECTRIC LIGHT FOR THE MAIN STREET",
              "The towns along the railroad are putting up electric lamps on their main streets, and the people come out at night just to stand under them.",
              "They're putting up electric lights on main street. Folks come out at night just to stand under them.",
              "Electric light at the hotel now. Turn a key and the room's bright as noon. Can't sleep for it."),
            E("phonograph", 1899, 0, 0, null, 1, "wonder", "THE TALKING MACHINE IN THE PARLOR",
              "Mr. Edison's phonograph and the graphophone are sold on time payments now, and a wax cylinder of a band or a song costs fifty cents.",
              "They've got a phonograph at the saloon. Sousa's band out of a horn, and the band never gets drunk.",
              "A talking machine in the parlor. A dead man could sing to his grandchildren off a wax tube. Preacher hates it."),
            E("movingpictures", 1899, 0, 0, null, 2, "wonder", "THE PICTURE MACHINE IN THE OPERA HOUSE",
              "The picture men throw the Corbett fight and the charge at San Juan on a sheet in the opera houses, and the people duck when a train comes at them.",
              "Saw a train come at me on a sheet in the opera house. Half the room ducked. I'd like to say I didn't.",
              "Pictures that move, thrown on a sheet. The Corbett fight, round by round, for a quarter. Like a ghost show."),
            E("bicyclecheap", 1899, 0, 0, null, 1, "life", "THE WHEEL COMES DOWN TO TWENTY-FIVE DOLLARS",
              "A bicycle that cost a hundred dollars three years ago sells for twenty-five, and the craze that filled the roads has settled into ordinary use.",
              "Bicycles are cheap now. Twenty-five dollars. Everybody who wanted one has one, and the rest of us are safe.",
              "A wheel for twenty-five dollars. The doctor goes on one, and the preacher too. The horses have quit minding."),
            E("ladieswheel", 1899, 0, 0, null, 1, "life", "THE LADIES ON THEIR WHEELS",
              "Women ride bicycles in every city in divided skirts and bloomers, and the old ladies say it is the end of modesty and the doctors say it is health.",
              "Women on bicycles in bloomers. The doctor says it's healthy. Ma says it's the end of the world.",
              "A girl rode through town on a wheel in bloomers. Ten men fell off the porch. She never looked round."),
            E("kodak", 1899, 0, 0, null, 1, "wonder", "YOU PRESS THE BUTTON",
              "The Kodak camera is a box anybody can use: press the button, send the box to Rochester, and the pictures come back by mail.",
              "Fellow took my picture with a Kodak box. Sends it off and the pictures come back in the mail. We'll see.",
              "Kodaks everywhere. A man can't scratch himself without somebody making a picture of it for the family."),
            E("xray", 1899, 0, 0, null, 1, "wonder", "THE X-RAY IN THE DOCTOR'S OFFICE",
              "The doctors in the cities see through flesh with the X-ray now and find a bullet or a broken bone without cutting.",
              "Doctors in Denver have the X-ray machine that sees through you. Finds the bullet without the knife.",
              "They photograph the bones in a living hand now. Grandma says that's witchcraft. She's not all wrong."),
            E("typewritergirl", 1899, 0, 0, null, 1, "life", "GIRLS AT THE TYPEWRITER",
              "Every office of any size has its typewriter girl now, and the young women earn more at the machine than at the loom or the school.",
              "Girls work the typewriters in the offices now. Eight dollars a week. More than a schoolteacher gets.",
              "My girl wants to typewrite in the city. I asked what's wrong with marrying. Eight dollars a week, she said."),
            E("rfd", 1899, 0, 0, "west", 1, "life", "THE MAIL TO COME TO THE FARM GATE",
              "Rural free delivery is spreading county by county, and a farmer on a route gets his paper and his letters at his own gate instead of riding to town.",
              "Rural free delivery on the east road. A man brings the mail to your gate. No excuse to go to town now.",
              "Free mail delivery on the farms. The paper comes the day it's printed. The storekeeper will lose his loafers."),
            E("searscatalogue", 1899, 0, 0, null, 2, "life", "THE BIG BOOK FROM CHICAGO",
              "Sears, Roebuck's catalogue runs to near a thousand pages this year, with everything from a plow to a wedding dress, and the storekeepers call it the ruin of the small town.",
              "The Sears book came, near a thousand pages. My wife's read it twice like a novel. The storekeeper hates it.",
              "Everything in the Chicago catalogue is cheaper than the store. Guns, stoves, corsets. The store's scared."),
            E("montgomeryward", 1899, 0, 0, null, 1, "life", "MONTGOMERY WARD AND THE GRANGE",
              "Montgomery Ward's book still goes out to every Grange hall, and a farmer can furnish a house from it without seeing a clerk's face.",
              "Ward's catalogue or Sears'. The two fight over every farm in the country. The storekeeper loses either way.",
              "Ordered a stove out of the Ward book. Came on the railroad in a crate. Didn't shake a hand the whole time."),
            E("patentmedicine", 1899, 0, 0, null, 2, "life", "THE MEDICINES THAT CURE EVERYTHING",
              "Peruna, Swamp-Root and Mrs. Pinkham's Compound sell by the millions of bottles, and every paper in the land takes the money for the advertisements.",
              "Peruna for catarrh, Swamp-Root for the kidneys, Pinkham's for the ladies. Half the paper's medicine now.",
              "Those patent tonics are half whiskey, the doctor says. That's why the temperance women take them for nerves."),
            E("smallpox", 1899, 0, 0, null, 2, "disaster", "SMALLPOX IN THE TOWNS AND THE QUARREL OVER THE NEEDLE",
              "Smallpox has broken out in towns across the West and the health officers vaccinate by force where the people will not come, and the people fight it.",
              "Smallpox in two towns down the line. The doctor's scratching every arm. Some say the scratch is worse.",
              "They quarantined a boarding house for smallpox. Yellow flag on the door. The vaccination man needed a guard."),
            E("consumptioncure", 1899, 0, 0, "high", 1, "life", "THE CONSUMPTIVES COME TO THE MOUNTAINS",
              "The doctors send their consumptives to Colorado for the dry air, and every town in the mountains has its tents and its cottages of the coughing.",
              "Every train brings lungers from the East. Doctors send them for the air. Colorado Springs coughs politely.",
              "An Ohio man came west for his lungs. Sleeps in a tent in the snow, doctor's orders. Says he's better."),
            E("newfoods", 1899, 0, 0, null, 1, "life", "THE NEW FOODS IN BOXES",
              "Breakfast comes in a box now, Grape-Nuts and Cream of Wheat and the rest, and the grocers say the oatmeal barrel is going the way of the buffalo.",
              "Breakfast out of a box now. Grape-Nuts. The grocer says it cures everything. Tastes like gravel.",
              "My wife buys breakfast food with a name on it and a doctor's picture. Oatmeal was good enough for Grant."),
            E("uneeda", 1899, 0, 0, null, 1, "life", "THE CRACKER IN THE PAPER BOX",
              "The biscuit trust sells its crackers in a sealed paper box with a boy in a slicker on it, and the cracker barrel at the store is emptying.",
              "Crackers in a box now, Uneeda. Boy in a raincoat on the lid. The old cracker keg's got no sitters left.",
              "Five cents for a box of crackers with a name. Loose ones were a cent a handful. Progress is a sealed package."),
            E("coffeetobacco", 1899, 0, 0, "west", 1, "life", "ARBUCKLES' AND BULL DURHAM",
              "Arbuckles' coffee in the paper sack with the peppermint stick in it, and Bull Durham in the little cloth bag, go out on every chuck wagon and in every saddlebag.",
              "Arbuckles' in the sack, a candy stick at the bottom for whoever grinds it. The cook's never short of help.",
              "Bull Durham in the little sack. The boys roll it in the saddle at a lope and lose half to the wind."),
            E("blackeagle", 1899, 0, 0, null, 1, "money", "A NEW DOLLAR BILL WITH AN EAGLE",
              "The Treasury's new silver certificate for a dollar has a great black eagle spread across it, with Lincoln and Grant below, and the people call it the black eagle.",
              "Seen the new dollar bill? Big black eagle on it, Lincoln and Grant underneath. Money I like the look of.",
              "The black eagle dollar. The storekeeper holds it up to the light like it's counterfeit. It's only new."),
            E("fiveandten", 1899, 0, 0, null, 1, "life", "THE FIVE AND TEN",
              "Woolworth's five and ten cent stores have spread to fifty-odd cities, and the ladies walk the counters for an hour and spend a quarter.",
              "There's a five and ten in the city now. Nothing over a dime. My wife came out with a bag and no change.",
              "Everything a nickel or a dime at Woolworth's. How do they make money? Volume, the clerk said."),
            // ---- the songs, the books, the shows ---------------------------------------------------------------
            E("hellomababy", 1899, 0, 0, null, 2, "life", "THE SONG OF THE YEAR",
              "Hello Ma Baby, a song of courting down a wire, is sung on every corner, played on every piano, and whistled by every boy in the land.",
              "Hello ma baby, hello ma honey. Can't walk a block without hearing it. Every boy in town whistles it.",
              "That hello-ma-baby song. Every piano in every saloon. I hated it the first week and I'm humming it now."),
            E("wildirishrose", 1899, 0, 0, null, 1, "life", "MY WILD IRISH ROSE",
              "Mr. Olcott's My Wild Irish Rose is the ballad of the year, sung by every tenor in every hall and by every Irishman after the third glass.",
              "My Wild Irish Rose. The Irish boys sing it at the third drink and cry at the fourth. Fine, the first time.",
              "Olcott's Irish song is on every parlor piano. My daughter sings it to the cat."),
            E("ragtime", 1899, 0, 0, null, 2, "life", "RAGTIME SWEEPS THE COUNTRY",
              "The ragged time of the piano players of St. Louis and Sedalia is the music of the year, in the halls and the parlors and even in the bands.",
              "Ragtime. Every piano player plays it now, and the bands too. The old folks call it a jig. The young dance.",
              "That ragtime music. Can't keep your feet still and can't tell how it's done. All in the left hand, they say."),
            E("cakewalk", 1899, 0, 0, null, 1, "life", "THE CAKEWALK CRAZE",
              "The cakewalk is danced in the finest ballrooms of New York now, strutting and high-stepping to ragtime, with a cake for the best couple.",
              "They're doing the cakewalk in the city ballrooms now. Strutting with the back arched. A cake for the winner.",
              "Cakewalk at the Grange hall Saturday. The blacksmith won the cake, sixteen stone of him high-stepping."),
            E("sousa", 1899, 0, 0, null, 1, "life", "SOUSA'S BAND ON TOUR",
              "Sousa's band is on the road again from coast to coast, and a town that gets a night of it talks of the Stars and Stripes Forever for a year.",
              "Sousa's band came through on the railroad. Stars and Stripes Forever. I'd have marched to war right then.",
              "The March King's touring, Sousa. A dollar a seat and worth two. Sixty men and every one can play."),
            E("davidharum", 1899, 0, 0, null, 2, "life", "DAVID HARUM, THE HORSE TRADER EVERYBODY QUOTES",
              "David Harum, the novel of a country banker and horse trader, has sold by the hundred thousand, and his sayings are repeated in every livery stable.",
              "Everybody's quoting David Harum. Do unto the other feller the way he'd do unto you, and do it first.",
              "That David Harum book. A horse trader smarter than the city men. Country folks like to see themselves win."),
            E("knighthoodnovels", 1899, 0, 0, null, 1, "life", "THE COSTUME NOVELS",
              "When Knighthood Was in Flower and Hugh Wynne sell by the hundred thousand, and the lending libraries cannot keep a costume novel on the shelf.",
              "All the novels are about the old days now. Knights and the Revolution. The present's too dull to read.",
              "My wife's read three of those costume novels running, every one with a duel in it. I'm watching my back."),
            E("mrdooley", 1899, 0, 0, null, 2, "life", "MR. DOOLEY ON EVERYTHING",
              "Mr. Dooley, the Chicago saloonkeeper of Mr. Dunne's newspaper pieces, is quoted in the Senate and the saloon alike, and his book sells with the Bible.",
              "Did you read Mr. Dooley this week? On the Philippines. The man says it so you can't be angry with him.",
              "Mr. Dooley, the Chicago saloonkeeper in the paper. The Irishman says what the rest of us only think."),
            E("dunbar", 1899, 0, 0, null, 1, "life", "THE POET DUNBAR",
              "Paul Laurence Dunbar, the young poet of Dayton, reads his verses to full halls across the country, and his books sell in every bookshop.",
              "That young poet Dunbar read in the city. Full hall. Some poems in plain talk, some fine as the Bible.",
              "Paul Dunbar's verses are in every bookshop. A poet who sounds like folks talk. My wife reads him aloud."),
            E("gibsongirl", 1899, 0, 0, null, 1, "life", "THE GIBSON GIRL",
              "Mr. Gibson's drawings of the tall, proud American girl in the magazines have every young woman in the country copying her hair and her shirtwaist.",
              "Every girl in town's copying the Gibson girl. Hair piled up, a shirtwaist, and that look down the nose.",
              "The Gibson girl in the magazines. Tall, proud, and never once smiles at the fellow drawing her."),
            E("funnypapers", 1899, 0, 0, null, 1, "life", "THE FUNNY PAPERS IN COLOR",
              "The Sunday papers print a page of funny pictures in color, the Katzenjammer Kids and the rest, and the children fight over it before church.",
              "The Sunday paper's got the Katzenjammer Kids in color. My boys fight over the funny page before church.",
              "Grown men reading the funny papers in the barber's chair. Two Dutch boys blowing up their uncle. I laughed."),
            E("buffalobill", 1899, 0, 0, "west", 2, "west", "BUFFALO BILL'S WILD WEST WITH SAN JUAN HILL",
              "Colonel Cody's Wild West has added the charge up San Juan Hill to the show this season, with Rough Riders and all, beside the Deadwood coach and the Indians.",
              "Buffalo Bill's doing San Juan Hill in the show now, beside the stagecoach and the Indians. Old West, new war.",
              "Cody's show has Rough Riders in it this year. Real ones, some. The West is a show and the war's a show."),
            E("annieoakley", 1899, 0, 0, "west", 1, "west", "LITTLE SURE SHOT",
              "Annie Oakley is with the Wild West again this season, breaking glass balls on the fly, and the papers say she shoots as she did at twenty.",
              "Annie Oakley's still with Cody's show. Shoots the ash off a cigar in a man's mouth. I'd not hold the cigar.",
              "Little Sure Shot, Annie Oakley. With Cody since '85. Outshoots every man in the show and don't say so."),
            E("houdini", 1899, 0, 0, "west", 1, "wonder", "THE HANDCUFF KING ON THE ORPHEUM CIRCUIT",
              "A young vaudeville man named Houdini is going round the Western theaters daring any police force to lock him up in their own irons, and none has held him yet.",
              "A fellow at the Orpheum gets out of any handcuffs the police bring. Houdini. The sheriff tried his own.",
              "Houdini, the handcuff king. Locked in the jail and out before the chief sat down. The police aren't amused."),
            E("tramps", 1899, 0, 0, null, 1, "life", "THE TRAMPS ON THE FREIGHTS",
              "The tramp army rides the freight cars from harvest to harvest and town to town, and the railroads' brakemen fight them off with clubs and lose.",
              "Tramps on every freight. Harvest hands, they say. The brakeman found nine in one car and let them be.",
              "A tramp came to the back door for a meal. Chopped wood an hour for it without being asked. Not all are bums."),
            // ---- the old West, and where it's got to -----------------------------------------------------------
            E("coleyounger", 1899, 0, 0, "west", 1, "west", "COLE YOUNGER STILL AT STILLWATER",
              "Cole Younger and his brother Jim are in their twenty-third year in the Minnesota penitentiary for the Northfield raid, and every year a petition goes up to pardon them.",
              "Cole Younger's still in Stillwater prison. Twenty-three years for Northfield. Turned religious, they say.",
              "There's a petition going round again to pardon the Youngers. Half of Missouri's signed it twice."),
            E("frankjames", 1899, 0, 0, "west", 1, "west", "FRANK JAMES TAKES TICKETS AT A THEATER",
              "Frank James, who rode with Quantrill and robbed trains with his brother Jesse, takes tickets at the door of a St. Louis theater and is a model citizen.",
              "Frank James takes tickets at a theater in St. Louis. The man robbed trains. Nobody argues about their seat.",
              "Jesse James's brother works a theater door in St. Louis and tips his hat. I'd pay just to hand him a ticket."),
            E("batmasterson", 1899, 0, 0, "west", 1, "west", "BAT MASTERSON WRITES UP THE FIGHTS",
              "Bat Masterson of Dodge City, who was a sheriff and a gambler, writes the sporting news for a Denver paper and referees the prize fights.",
              "Bat Masterson writes up the prize fights in a Denver paper. The pen's a safer line than the badge was.",
              "Masterson's a newspaperman now, Dodge City Bat. Faced down half of Dodge, and now he argues about rounds."),
            E("calamityjane", 1899, 0, 0, "west", 1, "west", "CALAMITY JANE IN MONTANA",
              "Calamity Jane is in Montana again, drinking with anyone who will stand it and selling her life story for a dime a copy.",
              "Calamity Jane came through on the train, drunk at noon and selling a book about herself. Half's made up.",
              "Saw Calamity Jane at the depot, an old woman in a man's hat. Says she scouted for Custer. Maybe she did."),
            E("geronimo", 1899, 0, 0, "west", 1, "west", "GERONIMO A PRISONER AT FORT SILL",
              "Geronimo, the Apache who held two armies off for years, is a prisoner of war at Fort Sill, grows melons, and sells his buttons to tourists.",
              "Geronimo's at Fort Sill growing watermelons. Sells the buttons off his coat to tourists and sews on more.",
              "Geronimo's a prisoner in Oklahoma. Fought the army for years. Now it feeds him and tourists buy his hat."),
            E("dawesrolls", 1899, 0, 0, "west", 1, "west", "THE COMMISSION ENROLLS THE FIVE TRIBES",
              "The Dawes Commission is writing down every Cherokee, Choctaw, Creek, Chickasaw and Seminole in the Indian Territory, to divide the tribal lands into farms.",
              "The Dawes men are writing down every Indian in the Territory, to cut the land up by the head.",
              "The Dawes rolls. Each Indian gets a farm and the nation gets nothing. The old chiefs won't sign."),
            E("khakikrag", 1899, 0, 0, null, 1, "war", "THE ARMY IN KHAKI",
              "The army wears khaki now in Cuba and the islands, with the Krag rifle and the canvas hat, and the blue wool coat of the old wars is gone to the closet.",
              "The soldiers wear brown now. Khaki, they call it. The old blue's done. My father's coat is a curiosity.",
              "Krag rifles and khaki cloth. A regiment looks like a line of dust now. I suppose that's the idea."),
            E("thirtyeight", 1899, 0, 0, null, 1, "war", "THE SOLDIERS WANT THE OLD FORTY-FIVE BACK",
              "The letters from the islands say the army's new thirty-eight revolver will not stop a man coming at you, and the officers are asking for the old forty-five.",
              "The boys write the army's thirty-eight don't stop a man. Hit him three times and he keeps coming.",
              "Army gave the soldiers a smaller pistol and the Filipinos don't respect it. A forty-five ends the argument."),
            E("armyhorses", 1899, 0, 0, "west", 1, "money", "THE ARMY BUYING HORSES FOR THE ISLANDS",
              "Army buyers are at the ranches and the sale barns for cavalry mounts and mules for the posts overseas, and a sound horse brings sixty dollars.",
              "Army's buying horses for the islands. Sixty dollars a head for a sound one. I'd sell the whole remuda.",
              "The cavalry buyer took twelve head off the ranch, cash. First cash the place has seen since roundup."),
            E("mainewreck", 1899, 0, 0, null, 1, "war", "THE MAINE STILL LIES IN HAVANA HARBOR",
              "The wreck of the Maine lies where she sank in Havana harbor with the dead still in her, and Congress has yet to vote the money to raise her.",
              "The Maine's still on the bottom at Havana with her crew in her. Remember the Maine, they said. Then forgot.",
              "They started a war over that ship, the Maine, and she's still lying in the mud. Says something."),
            E("sampsonschley", 1899, 0, 0, null, 1, "war", "SAMPSON OR SCHLEY, WHO WON AT SANTIAGO",
              "The navy still quarrels over whether Admiral Sampson or Commodore Schley won the battle off Santiago, and the papers have taken sides like a ball game.",
              "Still fighting over who won at Santiago. Sampson was off at a meeting and Schley was there. Take your side.",
              "Two admirals and one victory at Santiago. A year dividing it. The Spanish were quicker losing it."),
            E("antiimperialists", 1899, 0, 0, null, 1, "politics", "THE ANTI-IMPERIALISTS",
              "Mr. Carnegie and old Grover Cleveland are among the men of the Anti-Imperialist League, who say a republic cannot hold the Philippines and remain one.",
              "Carnegie and old Grover Cleveland are against keeping the Philippines. Strange company, those two.",
              "The Anti-Imperialist League says a republic can't own colonies and stay a republic. They may have a point."),
            // ---- the country ------------------------------------------------------------------------------------
            E("immigrants99", 1899, 0, 0, null, 1, "life", "THREE HUNDRED THOUSAND THROUGH THE GATES",
              "Above three hundred thousand immigrants will land this year, Italians and Poles and Hungarians most of them, and the cities swell and the farms do not.",
              "Three hundred thousand a year come through New York now. Italians, mostly. None of them out this far. Yet.",
              "A new crowd of immigrants every week in New York. They go to the mines and the mills. The farms get the rest."),
            E("womenvote", 1899, 0, 0, "west", 1, "politics", "WOMEN VOTE IN FOUR STATES",
              "Women vote in Wyoming, Colorado, Utah and Idaho, and the sky over the Rockies has not fallen.",
              "Women vote in Wyoming and Colorado. Have for years. The East thinks we're mad. Our saloons are no worse.",
              "Four Western states let women vote. Idaho, Utah, Colorado, Wyoming. My wife says the rest will come round."),
            E("drytowns", 1899, 0, 0, null, 1, "law", "THE DRY CRUSADE",
              "Kansas is dry by law and wet by custom, and the W.C.T.U. and the Anti-Saloon League are at every legislature with petitions to close the rest.",
              "Kansas has been dry for years. They sell whiskey as medicine there, by the pint, with a doctor's note.",
              "The Anti-Saloon League's here with petitions. The saloonkeeper joined the church to watch them close."),
            E("divorcecolony", 1899, 0, 0, "west", 1, "life", "THE DIVORCE COLONY AT SIOUX FALLS",
              "Rich Eastern wives live six months in the hotels of Sioux Falls, South Dakota, to get the divorce their own states will not give them.",
              "Rich New York wives live six months in Sioux Falls to get divorced. The town's never been so refined.",
              "Sioux Falls has made a trade of divorce. Six months and a judge. The East ships its unhappy wives out by rail."),
            E("boxers", 1899, 12, 20, "world", 1, "world", "THE BOXERS RISING IN CHINA",
              "A society in China calling itself the Boxers is burning the missions and killing converts, and the missionaries write home for warships.",
              "There's a society in China called the Boxers killing missionaries. The church collects for the missions.",
              "Boxers in China. A secret society that thinks it's bulletproof, the paper says. The navies will show them."),
            E("twainabroad", 1899, 0, 0, null, 1, "life", "MARK TWAIN STILL ABROAD",
              "Mark Twain is in Europe still, writing his way out of his debts, and every paper in America prints whatever he says to a reporter.",
              "Mark Twain's in Vienna, or London, paying his debts with lectures. A funny man in debt is the funniest kind.",
              "Twain's still abroad, broke, they say, and writing like fury. The reports of his death were exaggerated."),
            E("footballdeaths", 1899, 0, 0, null, 1, "sport", "THE COLLEGE GAME KILLS ANOTHER BOY",
              "Another college boy has died of football this season, and the faculties argue again whether the game should be stopped or merely tamed.",
              "Another boy killed at football at a college. They play it in a heap. The professors want it stopped.",
              "Football. Twenty-two boys in a pile and one carried off. And they call the prize ring brutal."),
            E("baseballone", 1899, 0, 0, null, 1, "sport", "ONE LEAGUE AND TWELVE CLUBS",
              "The National League has the game to itself with twelve clubs, and the small cities complain they cannot keep a player the big ones want.",
              "One ball league and twelve clubs, and the big cities buy any player the small ones find. Cleveland's proof.",
              "Baseball's all one league now, and the rich clubs own it. Same as everything else this year."),
            E("rice", 1899, 0, 0, "south", 1, "money", "THE RICE BOOM ON THE PRAIRIE",
              "The prairie west of the Atchafalaya is going under rice, with canals and pumps and Iowa farmers come down to grow it like wheat.",
              "Rice on the Louisiana prairie now. Iowa men came down with their reapers and flooded the grass.",
              "The rice farmers are pumping the bayous dry. Grow it like wheat, cut it with a binder. The bank likes it."),
            E("cottonlow", 1899, 0, 0, "south", 1, "money", "COTTON AT SIX CENTS",
              "Cotton brings six cents, and the planter who borrowed at ten against the crop owes the store more in December than he did in March.",
              "Six cents for cotton. You can't make it at six. Everybody owes the store and the store owes the bank.",
              "Cotton's down again. The more we grow the less it brings. There's a lesson nobody wants to learn."),
            E("bollweevil", 1899, 0, 0, "south", 1, "disaster", "THE WEEVIL IN THE TEXAS COTTON",
              "A Mexican beetle they call the boll weevil has eaten its way across the Texas cotton fields and is moving east a county or two a year.",
              "There's a bug in the Texas cotton, the boll weevil. Eats the boll from inside. Moving east every year.",
              "The weevil's in Texas. Nothing kills it. The planters burn the stalks and it comes back like a bill."),
            E("levees", 1899, 0, 0, "south", 1, "disaster", "THE LEVEES AND THE SPRING RISE",
              "The river commission builds the levees higher every year, and every spring the planters along the river watch the water and the weak places and pray.",
              "When the river's up the levee men walk it nights with lanterns. One crawfish hole and the parish drowns.",
              "They raised the levee two feet last year. The river came up three. That's Mississippi arithmetic."),
            E("sugarcuba", 1899, 0, 0, "south", 1, "money", "CUBAN SUGAR AND THE LOUISIANA PLANTER",
              "The Louisiana sugar planters fear that Cuban sugar will come in free now the island is ours, and have sent their men to Washington to keep the duty.",
              "The sugar men fear Cuba. Free sugar from our new island and the cane here is done. They've sent a lobby East.",
              "We fought for Cuba, and now Cuba's sugar will put ours out of business. Gratitude, the planters call it."),
            E("deadwoodtales", 1899, 0, 0, "west", 1, "west", "THE OLD-TIMERS AND THE OLD DAYS",
              "The men who saw the buffalo and the Sioux and the first railroad are old now, and the Eastern magazines pay them to remember it bigger than it was.",
              "Old Hank's got a magazine writer following him with a notebook, remembering things that never happened.",
              "The magazines pay for the old days now. Every man who ever saw a buffalo is Wild Bill in his own story."),
            E("hottime", 1899, 0, 0, null, 1, "life", "THE ROUGH RIDERS' SONG",
              "A Hot Time in the Old Town Tonight, the song the Rough Riders sang going up the hill, is still the tune every band strikes up when the flag goes by.",
              "The band plays Hot Time whenever the flag comes past. The Rough Riders sang it in Cuba. A national anthem now.",
              "There'll be a hot time in the old town tonight. Three years old, and the boys still sing it like it's new."),
            E("telephone", 1899, 0, 0, null, 1, "life", "THE TELEPHONE SPREADS",
              "With the Bell patents run out, new companies are stringing telephone wire into the small towns and along the farm roads, and a girl at the exchange puts the calls through.",
              "Telephone wire's going up along the farm roads back East. Next they'll be ringing the cows home.",
              "Saint Denis has telephones in the big houses. A man can be rude to his neighbour without leaving his chair.",
              "Talked into a telephone once in Saint Denis. A girl at the exchange put me through. Felt a fool, shouting.")
        };
    }
}
